/** Narrow a `ThreadItem` to one variant, e.g. `CodexItem<"commandExecution">`. */
export type CodexItem<K extends ThreadItem["type"]> = Extract<ThreadItem, { type: K }>;

// ---------------------------------------------------------------------------
// Wire envelopes
// ---------------------------------------------------------------------------

/**
 * app-server speaks JSON-RPC-shaped messages over stdio, one per LF-terminated
 * line. Four envelopes arrive from the server, distinguished by which of
 * `id` / `method` / `result` / `error` are present:
 *
 * - `{id, result}` / `{id, error}` -- a response to a request we sent
 * - `{id, method, params}` -- a `ServerRequest`; the turn BLOCKS until answered
 * - `{method, params}` -- a notification
 */
export type CodexResponse =
	| { id: RequestId; result: unknown; error?: never }
	| { id: RequestId; result?: never; error: { code: number; message: string; data?: unknown } };

/** Generated discriminated unions; aliases keep adapter imports local. */
export type CodexServerRequest = ServerRequest;
export type CodexNotification = ServerNotification;

export type CodexServerMessage = CodexResponse | CodexServerRequest | CodexNotification;

export function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isCodexResponse(msg: CodexServerMessage): msg is CodexResponse {
	return "id" in msg && !("method" in msg);
}

export function isCodexServerRequest(msg: CodexServerMessage): msg is CodexServerRequest {
	return "id" in msg && "method" in msg;
}

export function isCodexNotification(msg: CodexServerMessage): msg is CodexNotification {
	return !("id" in msg) && "method" in msg;
}

/** A typed lookup key for one app-server's wire namespace (`0` !== `"0"`). */
export function wireRequestKey(id: RequestId): string {
	return JSON.stringify([typeof id, id]);
}

/**
 * Server requests that block a turn and whose decline shape we know, so
 * `reply(id, null)` can decline rather than erroring the request out.
 * Sourced from `ServerRequest.ts` + the matching `*Response` types.
 */
export const DECLINE_RESPONSES: Readonly<Record<string, unknown>> = {
	"item/commandExecution/requestApproval": {
		decision: "decline",
	} satisfies CommandExecutionRequestApprovalResponse,
	"item/fileChange/requestApproval": {
		decision: "decline",
	} satisfies FileChangeRequestApprovalResponse,
	"mcpServer/elicitation/request": {
		action: "decline",
		content: null,
		_meta: null,
	} satisfies McpServerElicitationRequestResponse,
};
